from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = set(v for row in grid for v in row) - {bg}
    candidates = []

    # Find dense rectangular fields of a color. Sparse marker cells inside a
    # field are errors; unrelated isolated marks do not form rectangles.
    for color in colors:
        for r0 in range(h):
            for r1 in range(r0 + 1, h):
                height = r1 - r0 + 1
                for c0 in range(w):
                    for c1 in range(c0 + 1, w):
                        width = c1 - c0 + 1
                        area = height * width
                        if area < 4:
                            continue
                        count = sum(grid[r][c] == color
                                    for r in range(r0, r1 + 1)
                                    for c in range(c0, c1 + 1))
                        if count / area >= 0.80:
                            candidates.append((area, count / area, count,
                                               r0, r1, c0, c1, color))

    # Prefer largest/highest-confidence rectangles; rectangles are separate
    # objects, so accepted regions should not overlap.
    candidates.sort(reverse=True)
    selected = []
    for area, density, count, r0, r1, c0, c1, color in candidates:
        if any(not (r1 < ar0 or r0 > ar1 or c1 < ac0 or c0 > ac1)
               for ar0, ar1, ac0, ac1, acolor in selected):
            continue
        # A smaller rectangle contained by a selected rectangle is redundant.
        selected.append((r0, r1, c0, c1, color))

    out = [[bg] * w for _ in range(h)]
    for r0, r1, c0, c1, color in selected:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                out[r][c] = color
    return out


