from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = set(v for row in grid for v in row) - {bg}
    # Prefix sums allow checking every rectangular candidate efficiently.
    pref = {}
    for color in colors:
        p = [[0] * (w + 1) for _ in range(h + 1)]
        for r in range(h):
            run = 0
            for c in range(w):
                run += grid[r][c] == color
                p[r + 1][c + 1] = p[r][c + 1] + run
        pref[color] = p

    candidates = []
    for color, p in pref.items():
        for r0 in range(h - 1):
            for r1 in range(r0 + 1, h):
                height = r1 - r0 + 1
                for c0 in range(w - 1):
                    for c1 in range(c0 + 1, w):
                        area = height * (c1 - c0 + 1)
                        n = p[r1 + 1][c1 + 1] - p[r0][c1 + 1] - p[r1 + 1][c0] + p[r0][c0]
                        if n / area >= 0.80:
                            candidates.append((area, n, r0, r1, c0, c1, color))

    # Keep the largest dense rectangles first. All other colors/noise are
    # erased; every cell in a detected rectangle is restored to its fill color.
    candidates.sort(reverse=True)
    chosen = []
    for area, n, r0, r1, c0, c1, color in candidates:
        if any(not (r1 < a0 or r0 > a1 or c1 < b0 or c0 > b1)
               for a0, a1, b0, b1, _ in chosen):
            continue
        chosen.append((r0, r1, c0, c1, color))

    out = [[bg for _ in range(w)] for _ in range(h)]
    for r0, r1, c0, c1, color in chosen:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                out[r][c] = color
    return out


