from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    shape_colors = {v for v, n in counts.items() if v != bg and n >= 10}
    out = [[bg] * w for _ in range(h)]
    components = []
    for color in shape_colors:
        seen = set()
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r, c) in seen:
                    continue
                q = deque([(r, c)])
                seen.add((r, c))
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and
                                (ny, nx) not in seen and grid[ny][nx] == color):
                            seen.add((ny, nx))
                            q.append((ny, nx))
                r0 = min(y for y, x in cells)
                r1 = max(y for y, x in cells)
                c0 = min(x for y, x in cells)
                c1 = max(x for y, x in cells)
                components.append((color, r0, r1, c0, c1))
                for y in range(r0, r1 + 1):
                    for x in range(c0, c1 + 1):
                        out[y][x] = color

    # If a one-cell marker splits a rectangle, a narrow foreground fragment
    # separated by exactly one column can be part of the same filled rectangle.
    for i, (color, r0, r1, c0, c1) in enumerate(components):
        for color2, a0, a1, b0, b1 in components[i + 1:]:
            if (color == color2 and (r0, r1) == (a0, a1) and
                    b0 == c1 + 2 and b1 == c1 + 2):
                for y in range(r0, r1 + 1):
                    out[y][c1 + 1] = color
            if (color == color2 and (r0, r1) == (a0, a1) and
                    c0 == b1 + 2 and c1 == b1 + 2):
                for y in range(r0, r1 + 1):
                    out[y][b1 + 1] = color
    return out


