def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    # The picture uses the background plus its frequent foreground colors;
    # rarer colors are accidental speckles over or around those fields.
    main = {color for color, n in counts.items() if color != bg and n >= 10}
    out = [[v if v == bg or v in main else bg for v in row] for row in grid]

    for color in main:
        seen = set()
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r, c) in seen:
                    continue
                q = deque([(r, c)])
                seen.add((r, c))
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and
                                (ny, nx) not in seen and grid[ny][nx] == color):
                            seen.add((ny, nx))
                            q.append((ny, nx))
                r0 = min(y for y, x in cells)
                r1 = max(y for y, x in cells)
                c0 = min(x for y, x in cells)
                c1 = max(x for y, x in cells)
                area = (r1-r0+1) * (c1-c0+1)
                if r1 > r0 and c1 > c0 and len(cells) / area >= 0.50:
                    for y in range(r0, r1+1):
                        for x in range(c0, c1+1):
                            out[y][x] = color
    return out


