from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg] * w for _ in range(h)]
    colors = {v for row in grid for v in row if v != bg}

    # Identify independent clean rectangular patches (with sparse damaged cells)
    # by their row/column spans. Require multi-row and multi-column support.
    for color in colors:
        positions = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if len(positions) < 4:
            continue
        # Split same-color points into nearby groups so disconnected patches
        # do not become one enormous bounding box.
        remaining = set(positions)
        while remaining:
            seed = remaining.pop()
            group = {seed}
            frontier = [seed]
            while frontier:
                r, c = frontier.pop()
                near = [(rr, cc) for rr, cc in list(remaining)
                        if max(abs(rr-r), abs(cc-c)) <= 1]
                for cell in near:
                    remaining.remove(cell)
                    group.add(cell)
                    frontier.append(cell)
            r0 = min(r for r, c in group); r1 = max(r for r, c in group)
            c0 = min(c for r, c in group); c1 = max(c for r, c in group)
            area = (r1-r0+1)*(c1-c0+1)
            if r1 == r0 or c1 == c0:
                continue
            if len(group) / area >= 0.50 and area >= 6:
                for r in range(r0, r1+1):
                    for c in range(c0, c1+1):
                        out[r][c] = color
    return out


