from collections import Counter


def _rectangles(grid, color, bg):
    h, w = len(grid), len(grid[0])
    active = [[grid[r][c] == color for c in range(w)] for r in range(h)]
    rects = []
    # Find dense rectangular patches. Selecting largest patches first separates
    # a one-row spur from the main rectangle instead of expanding its bbox.
    while True:
        best = None
        for r0 in range(h - 1):
            for r1 in range(r0 + 1, h):
                for c0 in range(w - 1):
                    for c1 in range(c0 + 1, w):
                        area = (r1-r0+1) * (c1-c0+1)
                        if area < 4:
                            continue
                        n = sum(active[r][c] for r in range(r0, r1+1)
                                for c in range(c0, c1+1))
                        density = n / area
                        if density < 0.72:
                            continue
                        score = area * density
                        if best is None or score > best[0]:
                            best = (score, r0, r1, c0, c1)
        if best is None:
            break
        _, r0, r1, c0, c1 = best
        rects.append((r0, r1, c0, c1))
        for r in range(r0, r1+1):
            for c in range(c0, c1+1):
                active[r][c] = False
    return rects


