from collections import Counter, deque


def components(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if (0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy,xx)); q.append((yy,xx))
            r0, r1 = min(y for y,x in cells), max(y for y,x in cells)
            c0, c1 = min(x for y,x in cells), max(x for y,x in cells)
            result.append({'color':color, 'cells':cells, 'box':(r0,r1,c0,c1),
                           'shape':frozenset((y-r0,x-c0) for y,x in cells)})
    return bg, result


def l_corner(obj):
    cells = obj['cells']; r0,r1,c0,c1 = obj['box']
    for r in (r0,r1):
        for c in (c0,c1):
            horizontal = {(r,x) for x in range(c0,c1+1)}
            vertical = {(y,c) for y in range(r0,r1+1)}
            if horizontal | vertical == cells:
                return r,c
    return None


def transform(grid):
    bg, objs = components(grid)
    guides = [(o,l_corner(o)) for o in objs if l_corner(o) is not None]
    if not guides:
        return [row[:] for row in grid]
    guide, corner = max(guides, key=lambda z: len(z[0]['cells']))
    r0,r1,c0,c1 = guide['box']; cr,cc = corner
    # The motif lies in the quadrant opposite the L's joined corner.
    inside = []
    for o in objs:
        if o is guide:
            continue
        if (all((y < cr if cr == r1 else y > cr) and
                (x < cc if cc == c1 else x > cc) for y,x in o['cells'])):
            inside.append(o)
    if not inside:
        return [row[:] for row in grid]
    motif = min(inside, key=lambda o: len(o['cells']))
    out = [row[:] for row in grid]
    for o in objs:
        if o is guide or o is motif or o['shape'] != motif['shape']:
            continue
        for y,x in o['cells']:
            out[y][x] = guide['color']
    return out

