def _components(grid, bg):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if (0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen
                            and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        q.append((yy, xx))
            comps.append((color, cells))
    return comps


def _shape(cells):
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    return frozenset((r-r0, c-c0) for r, c in cells)


def _guide_corner(cells):
    """Return an L's corner and the two arm directions, or None."""
    r0 = min(r for r, c in cells); r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells); c1 = max(c for r, c in cells)
    h, w = r1-r0+1, c1-c0+1
    if h < 2 or w < 2:
        return None
    for cr in (r0, r1):
        for cc in (c0, c1):
            vertical = {(r, cc) for r in range(r0, r1+1)}
            horizontal = {(cr, c) for c in range(c0, c1+1)}
            if vertical | horizontal <= cells:
                # The arms point from the corner along the two bbox edges.
                dr = 1 if cr == r0 else -1
                dc = 1 if cc == c0 else -1
                return cr, cc, dr, dc
    return None


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = _components(grid, bg)

    guides = []
    for color, cells in comps:
        corner = _guide_corner(cells)
        if corner:
            guides.append((len(cells), color, cells, corner))
    if not guides:
        return [row[:] for row in grid]
    _, guide_color, guide, (cr, cc, arm_dr, arm_dc) = max(guides, key=lambda x: x[0])

    # The component in the open quadrant opposite the guide's arms is the
    # pattern. Find its identical translated copy outside that quadrant.
    inside = []
    for color, cells in comps:
        if cells == guide:
            continue
        cy = sum(r for r, c in cells) / len(cells)
        cx = sum(c for r, c in cells) / len(cells)
        if (cy-cr)*arm_dr < 0 and (cx-cc)*arm_dc < 0:
            inside.append((color, cells))
    matches = []
    for pattern_color, pattern in inside:
        footprint = _shape(pattern)
        for color, cells in comps:
            if cells == guide or cells == pattern or _shape(cells) != footprint:
                continue
            cy = sum(r for r, c in cells) / len(cells)
            cx = sum(c for r, c in cells) / len(cells)
            if (cy-cr)*arm_dr >= 0 or (cx-cc)*arm_dc >= 0:
                matches.append((abs(cy-cr)+abs(cx-cc), cells))
    if not matches:
        return [row[:] for row in grid]
    target = min(matches, key=lambda x: x[0])[1]
    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = guide_color
    return out


