    # rails give the axis and the index mapping for projecting marker lines.
    options = []
    for orientation, first, second in (
        ('horizontal', runs(grid[0]), runs(grid[-1])),
        ('vertical', runs([grid[r][0] for r in range(h)]),
         runs([grid[r][-1] for r in range(h)])),
    ):
        for a in first:
            for b in second:
                if a[2] == b[2] and a[1] - a[0] == b[1] - b[0]:
                    options.append((a[1] - a[0], orientation, a, b))
    if not options:
        return out
    _, orientation, rail_a, rail_b = max(options, key=lambda item: item[0])
    rails = (rail_a, rail_b)
    rail_color = rail_a[2]

    clues = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            color = grid[r][c]
            if color in (background, rail_color):
