    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find equal-length colored runs on opposing borders. A marker aligned
    # with one run shoots toward that border; its offset is projected onto
    # the matching run at the opposite border as a full interior stripe.
    candidates = []
    for axis in (0, 1):  # 0: top/bottom runs; 1: left/right runs
        span = w if axis == 0 else h
        edge0 = grid[0][:] if axis == 0 else [grid[r][0] for r in range(h)]
        edge1 = grid[-1][:] if axis == 0 else [grid[r][-1] for r in range(h)]
        runs0, runs1 = _runs(edge0, background), _runs(edge1, background)
        for run0 in runs0:
            for run1 in runs1:
                if run0[2] == run1[2] and run0[1] - run0[0] == run1[1] - run1[0]:
                    candidates.append((run0[1] - run0[0], axis, run0, run1))
    if not candidates:
