            for d in range(1, depth - 1):
                color = get(pos, d)
                if color != background and color != run0[2]:
                    markers.append((side, pos, d, color))

    for side, pos, d, color in markers:
        run = run0 if side == 0 else run1
        other = run1 if side == 0 else run0
        projected_pos = other[0] + (pos - run[0])

        # Extend the marker toward the border whose rail contains it.
        if side == 0:
            for q in range(1, d):
                put(pos, q, color)
        else:
            for q in range(d + 1, depth - 1):
                put(pos, q, color)

        # Copy its position across the paired rails as an interior stripe.
        for q in range(1, depth - 1):
            put(projected_pos, q, color)

    for side, pos, d, _color in markers:
