def transform(grid):
    """Complete the less populated of aligned, repeated foreground bands.

    Among equal-height separated bands, select the pair with the strongest
    exact foreground overlap. The richer copy is the reference; mark its
    foreground cells missing in the other copy with color 1.
    """
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    bands = []
    r = 0
    while r < h:
        if all(v == bg for v in grid[r]):
            r += 1
            continue
        start = r
        while r < h and any(v != bg for v in grid[r]):
            r += 1
        bands.append((start, r))

    best = None
    for i, (a0, a1) in enumerate(bands):
        for b0, b1 in bands[i + 1:]:
            if a1 - a0 != b1 - b0:
                continue
            height = a1 - a0
            overlap = sum(
                grid[a0+k][c] == grid[b0+k][c] and grid[a0+k][c] != bg
                for k in range(height) for c in range(w)
            )
            if overlap < 2:
                continue
            count_a = sum(grid[a0+k][c] != bg for k in range(height) for c in range(w))
            count_b = sum(grid[b0+k][c] != bg for k in range(height) for c in range(w))
            key = (overlap, min(count_a, count_b), -abs(count_a-count_b))
            if best is None or key > best[0]:
                best = (key, a0, b0, height, count_a, count_b)

    out = [row[:] for row in grid]
    if best is not None:
        _, a0, b0, height, count_a, count_b = best
        if count_a >= count_b:
            src0, dst0 = a0, b0
        else:
            src0, dst0 = b0, a0
        for k in range(height):
            for c in range(w):
                if grid[src0+k][c] != bg and grid[dst0+k][c] == bg:
                    out[dst0+k][c] = 1
    return out


