def transform(grid):
    """Extend same-color diagonal pairs along their diagonal, through background."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    for dr, dc in ((1, 1), (1, -1)):
        # Enumerate each diagonal exactly once, starting at its boundary cell.
        for r in range(h):
            for c in range(w):
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w:
                    continue
                line = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w:
                    line.append((rr, cc))
                    rr += dr
                    cc += dc
                # Any adjacent equal-color pair anchors a complete line through
                # that pair; grow outward from each end until an occupied cell.
                for i in range(len(line) - 1):
                    y1, x1 = line[i]
                    y2, x2 = line[i + 1]
                    color = grid[y1][x1]
                    if color == bg or grid[y2][x2] != color:
                        continue
                    j = i - 1
                    while j >= 0:
                        y, x = line[j]
                        if grid[y][x] != bg:
                            break
                        out[y][x] = color
                        j -= 1
                    j = i + 2
                    while j < len(line):
                        y, x = line[j]
                        if grid[y][x] != bg:
                            break
                        out[y][x] = color
                        j += 1
    return out

